import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

function App() {
  const [model, setModel] = React.useState(appsmith.model || {});

  React.useEffect(() => {
    const handleModelChange = (newModel) => {
      if (newModel) setModel(newModel);
    };
    appsmith.onModelChange(handleModelChange);
  }, []);

  const handleTileClick = (filterValue, e) => {
    if (e) e.stopPropagation();
    if (filterValue) {
      if (appsmith.updateModel) {
        // Toggle logic: If clicking the already selected filter, deselect it (empty string)
        const newFilter = model.selectedFilter === filterValue ? "" : filterValue;
        appsmith.updateModel({ clickedFilter: newFilter });
      }
      if (appsmith.triggerEvent) {
        appsmith.triggerEvent("onTileClick");
      }
    }
  };

  if (!model.tiles || !Array.isArray(model.tiles)) {
    return (
      <div style={{ padding: "20px", textAlign: "center", fontFamily: "system-ui, sans-serif", color: "#64748b" }}>
        Loading Dashboard Metrics...
      </div>
    );
  }

  return (
    <div
      className="dashboard-container"
      style={{
        gridTemplateColumns: `repeat(${model.layout?.columns || 4}, 1fr)`,
        gridAutoRows: "130px", // Fixed height so span 2 works without breaking rows
        gap: model.layout?.gap || "20px"
      }}
    >
      {[...model.tiles].sort((a, b) => (a.SortOrder || 0) - (b.SortOrder || 0)).map((tile) => (
        <div
          key={tile.FilterValue || tile.TileName}
          className={`dashboard-tile ${tile.SubTiles?.length > 0 ? 'has-subtiles' : ''} ${model.selectedFilter === tile.FilterValue ? 'is-selected' : ''}`}
          onClick={(e) => handleTileClick(tile.FilterValue, e)}
          style={{ backgroundColor: tile.BgColor, color: tile.TextColor }}
        >
          <div className="tile-header-container">
            <div className="tile-info">
              {tile.Icon && <span className="tile-icon" dangerouslySetInnerHTML={{ __html: tile.Icon }}></span>}
              <div className="tile-name">{tile.TileName}</div>
              <div className="tile-count">{tile.TileCount}</div>
            </div>
            {tile.SortOrder && (
              <div className="tile-sequence-badge">
                {tile.SortOrder}
              </div>
            )}
          </div>

          {/* SUB-TILES RENDER BLOCK */}
          {tile.SubTiles && tile.SubTiles.length > 0 && (
            <div className="sub-tiles-container">
              {tile.SubTiles.map((sub) => (
                <div
                  key={sub.FilterValue || sub.TileName}
                  className={`sub-tile ${model.selectedFilter === sub.FilterValue ? 'is-selected' : ''}`}
                  onClick={(e) => handleTileClick(sub.FilterValue, e)}
                >
                  <div className="sub-tile-name">{sub.TileName}</div>
                  <div className="sub-tile-count">{sub.TileCount}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

appsmith.onReady(() => {
  ReactDOM.render(<App />, document.getElementById("root"));
});
